//! The playable and enemy kinds at a preset's scale (M5 C12b): the shipped content with the figures
//! `bench/kinds.ron` names made again at that scale, under the same IDs, for a cook into `target/` and
//! nothing else.
//!
//! The party's kinds ship small (Wren 7,056 triangles, Aster 6,944, maps of 256), which is what the
//! goldens and CI cook. Exit test 5 asks for them at spec §3.4's hero row. [`generate`] links every file
//! of the content directory into a tree of its own, then writes over each named figure's generated files
//! ([`figure::figure_files`]: the model, the maps, the face masks and the matcap) what its committed spec
//! makes under the document's [`FigureScale`], the cast's one scale ([`FigureScale::apply`]). The
//! hand-written sidecars and documents are the shipped ones, so every ID stands and the same scenario,
//! replay and documents play at the row. Only a map over spec §3.4's size a cook stores gets that cook's
//! cap in its sidecar (`cast::map_cap`), as the cast's do, with its ID kept.
//!
//! A file is written over only after it's unlinked, so the content it was linked from never changes, and
//! the tree must be missing, empty or one this wrote ([`super::MARKER`]).

use std::fs;
use std::io;
use std::path::Path;

use bevy_reflect::TypePath;
use sapphire_reflect::Versioned;
use serde::{Deserialize, Serialize};

use super::cast::{FigureScale, map_cap};
use super::{BenchError, MARKER, Preset, Presets, read_document};
use crate::character_maps::MapSettings;
use crate::figure::{self, Figure, FileKind, Surface};
use crate::meta::{self, ImportSettings};
use crate::texture::MaxSize;

/// The kinds' document in `bench/`.
pub const DOCUMENT: &str = "kinds.ron";

/// `bench/kinds.ron` (`sapphire::pipeline::BenchKinds`): which shipped figures a preset makes again, and how.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, TypePath)]
#[type_path = "sapphire::pipeline"]
#[serde(deny_unknown_fields)]
pub struct BenchKinds {
    pub kinds: Vec<Kind>,
}

impl Versioned for BenchKinds {
    /// 1: M5 C12b.
    const VERSION: u32 = 1;
}

/// One shipped figure, by its spec's name in the specs folder (`tools/figures/`).
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Kind {
    pub spec: String,
    /// What each preset makes of it: none leaves it as it ships. One copy: a kind is its IDs.
    pub presets: Presets<Option<FigureScale>>,
}

/// The specs `preset` makes again, as it makes them, from the document in `bench` and the specs in `specs`.
pub fn figures(bench: &Path, specs: &Path, preset: Preset) -> Result<Vec<Figure>, BenchError> {
    let path = bench.join(DOCUMENT);
    let document: BenchKinds = read_document(&path)?;
    let invalid = |why: String| BenchError::Invalid { path: path.clone(), why };
    let mut figures: Vec<Figure> = Vec::new();
    for kind in &document.kinds {
        let Some(scale) = kind.presets.get(preset) else { continue };
        if scale.copies != 1 {
            return Err(invalid(format!("{}: a kind is one figure under its IDs, so one copy", kind.spec)));
        }
        let mut figure = figure::read(&specs.join(format!("{}{}", kind.spec, figure::SPEC_EXTENSION)))?;
        scale.apply(&mut figure).map_err(|why| invalid(format!("{}: {why}", kind.spec)))?;
        if figures.iter().any(|other| other.dir == figure.dir && other.name == figure.name) {
            return Err(invalid(format!("{} is named twice", kind.spec)));
        }
        figures.push(figure);
    }
    Ok(figures)
}

/// What [`generate`] did: the figures it made again and the files it wrote over, sidecars among them, by
/// their paths in the tree.
#[derive(Debug, Default)]
pub struct Regenerated {
    pub figures: Vec<String>,
    pub replaced: Vec<String>,
}

/// Makes `out` the content directory `content` with the figures `preset` makes again (see the module
/// docs), from the document in `bench` and the specs in `specs`.
pub fn generate(
    bench: &Path,
    specs: &Path,
    preset: Preset,
    content: &Path,
    out: &Path,
) -> Result<Regenerated, BenchError> {
    let figures = figures(bench, specs, preset)?;
    if out.is_dir() {
        if !out.join(MARKER).is_file() && fs::read_dir(out)?.next().is_some() {
            return Err(BenchError::NotGenerated(out.to_owned()));
        }
        fs::remove_dir_all(out)?;
    }
    fs::create_dir_all(out)?;
    link_tree(content, out)?;
    meta::replace_file(
        &out.join(MARKER),
        format!("Generated by `sapphire_pipeline gen-kinds --preset {preset}`: never commit it.\n")
            .as_bytes(),
    )?;
    let mut done = Regenerated::default();
    for figure in &figures {
        done.figures.push(figure.name.clone());
        replace(out, figure, &mut done.replaced)?;
    }
    Ok(done)
}

/// Writes `figure`'s files over the shipped ones in `out`, and its maps' cap into their sidecars.
fn replace(out: &Path, figure: &Figure, replaced: &mut Vec<String>) -> Result<(), BenchError> {
    let missing = |path: &str| BenchError::Invalid {
        path: out.join(path),
        why: format!("{} doesn't write it as it ships, so it has no sidecar or reader", figure.name),
    };
    let files = figure::figure_files(figure)?;
    let mut capped = Vec::new();
    for file in &files {
        let path = out.join(&file.path);
        if !path.is_file() {
            return Err(missing(&file.path));
        }
        write_unlinked(&path, &file.bytes)?;
        replaced.push(file.path.clone());
        if matches!(file.kind, FileKind::Palette(_) | FileKind::Layers(_)) {
            capped.push(file.path.clone());
        }
    }
    // The maps' own documents: an ILM over each control map, a face SDF over a face's masks.
    for group in figure.material_groups()? {
        capped.push(format!("{}/{}.ilm.ron", figure.dir, group.stem));
        if group.surface == Surface::Face {
            capped.push(format!("{}/{}.facesdf.ron", figure.dir, group.stem));
        }
    }
    let cap = map_cap(figure);
    if cap.is_none() {
        return Ok(());
    }
    for source in capped {
        let sidecar = meta::sidecar_path(&out.join(&source));
        let mut asset = meta::read(&sidecar)
            .map_err(|error| BenchError::Invalid { path: sidecar.clone(), why: error.to_string() })?;
        if !set_cap(&mut asset.importer, cap) {
            return Err(BenchError::Invalid {
                path: sidecar,
                why: "a map's sidecar that takes no cap: a texture, an ILM or a face SDF".to_owned(),
            });
        }
        let text = sapphire_serialize::to_ron(&asset).expect("a sidecar serializes");
        write_unlinked(&sidecar, text.as_bytes())?;
        replaced.push(meta::sidecar_path(Path::new(&source)).to_string_lossy().replace('\\', "/"));
    }
    Ok(())
}

/// Gives a map's importer `cap`, if it takes one.
fn set_cap(importer: &mut ImportSettings, cap: MaxSize) -> bool {
    match importer {
        ImportSettings::Texture(settings) => settings.max_size = cap,
        ImportSettings::CharacterMap(MapSettings::Ilm(_) | MapSettings::FaceSdf(_), max_size) => {
            *max_size = cap
        }
        _ => return false,
    }
    true
}

/// Writes `bytes` as `path` anew, never through a link to the file it was.
fn write_unlinked(path: &Path, bytes: &[u8]) -> io::Result<()> {
    fs::remove_file(path)?;
    meta::replace_file(path, bytes)
}

/// Links every file under `from` into `to`, keeping the tree, or copies one where the filesystem won't link.
fn link_tree(from: &Path, to: &Path) -> io::Result<()> {
    for entry in fs::read_dir(from)? {
        let entry = entry?;
        let (source, target) = (entry.path(), to.join(entry.file_name()));
        if entry.file_type()?.is_dir() {
            fs::create_dir_all(&target)?;
            link_tree(&source, &target)?;
        } else if fs::hard_link(&source, &target).is_err() {
            fs::copy(&source, &target)?;
        }
    }
    Ok(())
}

